head.script:
scwin.onpageload = function() {};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    wframe1.setSrc("wframe_treeView_customFormatter_WPFF-340_(WSQ-3843)_sub.xml");
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'wframe1_treeview1').childNodes.length == 1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //	scwin.treeviewFormatter = function(value, formattedValue, row, col) {
    //        debugger;
    //        return value+" Global formatter";
    //    };
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
